export const ALL_PERFORMANCE_FRAMEWORKS: PerformanceFramework[] = [
	FRAMEWORK_APPLY,
	FRAMEWORK_BACKEND_BUILD,
	FRAMEWORK_BACKEND_FIX,
	FRAMEWORK_BACKEND_IMPLEMENT,
	FRAMEWORK_COMPOSITION,
	FRAMEWORK_DOCS,
	FRAMEWORK_FRONTEND_BUILD,
	FRAMEWORK_FRONTEND_FIX,
	FRAMEWORK_FRONTEND_IMPLEMENT,
	FRAMEWORK_FRONTEND_REVIEW,
	FRAMEWORK_GENERATION,
	FRAMEWORK_PLAN_DESIGN,
	FRAMEWORK_PLAN_RESEARCH,
	FRAMEWORK_PLAN_SCOPE,
	FRAMEWORK_POLISH,
	FRAMEWORK_REFACTOR,
];

const FRAMEWORKS_BY_ID = new Map<string, PerformanceFramework>(
	ALL_PERFORMANCE_FRAMEWORKS.map((fw) => [fw.id, fw]),
);

export function getPerformanceFramework(id: string): PerformanceFramework | undefined {
	return FRAMEWORKS_BY_ID.get(id);
}

export function listPerformanceFrameworks(): PerformanceFramework[] {
	return [...ALL_PERFORMANCE_FRAMEWORKS];
}

export function searchFrameworksByCategory(category: string): PerformanceFramework[] {
	return ALL_PERFORMANCE_FRAMEWORKS.filter((fw) => fw.category === category || fw.category === "any");
}
